-- Unit tests
-- Request: RCM-1610 - Add Patient Financial Class to the AR Aging Report
-- Generated by the RCM change automation platform.

-- Suite: unit_tests_patient_financial_class
-- Data quality suite for rcm.fact_ar.patient_financial_class

-- [Column Population] column_population
-- Expectation: at least one populated row
-- Severity: blocking | Sandbox result: passed | observed: 12
SELECT COUNT(*) AS populated_rows
FROM rcm.fact_ar
WHERE patient_financial_class IS NOT NULL;

-- [Null Validation] null_validation
-- Expectation: 0 records
-- Severity: blocking | Sandbox result: passed | observed: 0
SELECT COUNT(*) AS null_rows
FROM rcm.fact_ar
WHERE patient_financial_class IS NULL;

-- [Row Count Validation] row_count_validation
-- Expectation: matches the source row count from staging.stg_ar_transactions
-- Severity: blocking | Sandbox result: passed | observed: 12 vs 12
SELECT COUNT(*) AS target_rows FROM rcm.fact_ar;

-- [Duplicate Validation] duplicate_validation
-- Expectation: 0 records
-- Severity: blocking | Sandbox result: passed | observed: 0
SELECT COUNT(*) AS duplicate_keys
FROM (
    SELECT claim_id
    FROM rcm.fact_ar
    GROUP BY claim_id
    HAVING COUNT(*) > 1
) duplicates;

-- [Data Type Validation] datatype_validation
-- Expectation: 0 records exceeding VARCHAR(50)
-- Severity: blocking | Sandbox result: passed | observed: 0
SELECT COUNT(*) AS oversized_values
FROM rcm.fact_ar
WHERE patient_financial_class IS NOT NULL
  AND LENGTH(patient_financial_class) > 50;

-- [Domain Validation] domain_validation
-- Expectation: 0 records outside the certified domain
-- Severity: blocking | Sandbox result: passed | observed: 0
SELECT COUNT(*) AS out_of_domain
FROM rcm.fact_ar
WHERE patient_financial_class IS NOT NULL
  AND patient_financial_class NOT IN ('Commercial', 'Medicare', 'Medicaid', 'Self Pay', 'Workers Comp');

-- [Source to Target Validation] source_to_target_parity
-- Expectation: 0 records where the fact value differs from the source dimension
-- Severity: blocking | Sandbox result: passed | observed: 0
SELECT COUNT(*) AS mismatched_rows
FROM rcm.fact_ar f
JOIN rcm.dim_patient s ON s.patient_key = f.patient_key
WHERE COALESCE(f.patient_financial_class, '~') <> COALESCE(s.patient_financial_class, '~');

-- [Reporting Layer Exposure] view_exposure_vw_ar_detail
-- Expectation: view compiles and exposes the new column
-- Severity: blocking | Sandbox result: passed | observed: 12
SELECT COUNT(*) AS exposed_rows
FROM rcm.vw_ar_detail
WHERE patient_financial_class IS NOT NULL;
